from typing import List

class Solution:
    def maxFrequency(self, nums: List[int], k: int) -> int:
        total_k = nums.count(k)
        best_gain = 0

        for v in range(1, 51):
            if v == k:
                continue

            cur = 0
            for num in nums:
                if num == v:
                    cur += 1
                elif num == k:
                    cur -= 1

                cur = max(cur, 0)
                best_gain = max(best_gain, cur)

        return total_k + best_gain
